fn hermeline(off: f64, scl: f64) -> Vec<f64> {
    // Create a vector with enough capacity for two elements
    let mut coeffs = Vec::with_capacity(2);

    // First element is always `off`
    coeffs.push(off);

    // Second element: if `scl` is exactly zero (including +0.0 or -0.0),
    // then yield +0.0. Otherwise, yield `scl` unchanged.
    let second = if scl == 0.0 { 0.0 } else { scl };
    coeffs.push(second);

    coeffs
}

fn main() {
    // Examples
    let v1 = hermeline(3.5, 0.0);
    assert_eq!(v1, vec![3.5, 0.0]);

    let v2 = hermeline(-1.2, 4.8);
    assert_eq!(v2, vec![-1.2, 4.8]);

    // Demonstrate handling of -0.0
    let v3 = hermeline(1.0, -0.0);
    // we normalize to +0.0 in the zero case
    assert_eq!(v3[1].to_bits(), 0.0f64.to_bits());

    println!("All tests passed!");
}